//! # oic-crypto-provider-frost-ed25519
//!
//! [`FrostEd25519Provider`]: one participant's instance of real
//! FROST(Ed25519, SHA-512) t-of-n threshold signing (RFC 9591) over the
//! pinned `frost-ed25519` crate, implementing [`CryptoProvider`].
//!
//! ## Security claim it makes
//!
//! * **Threshold:** keys are generated by the FROST distributed key
//!   generation ([`run_dkg`] drives the per-participant [`FrostEd25519Provider::dkg_part1`],
//!   [`FrostEd25519Provider::dkg_part2`], [`FrostEd25519Provider::dkg_part3`]); no
//!   party ever holds the group secret. Any `t` of `n` participants
//!   (`2 <= t <= n <= 16`) can sign; fewer cannot.
//! * **Native compatibility:** aggregated signatures are standard 64-byte
//!   Ed25519 (RFC 8032, pure) and are verified in [`CryptoProvider::verify_result`] with
//!   `ed25519-dalek` (`verify_strict`), not with frost.
//! * **Safety against a malicious participant (A05/A06):** `aggregate`
//!   verifies every signature share against the signer's public verification
//!   share (frost cheater detection); a bogus share yields an error naming the
//!   culprit and no signature.
//! * **Message binding:** before producing a share a participant checks that
//!   the coordinator's `SigningPackage` signs exactly the authorized session
//!   payload, contains exactly the session's participant set, and carries this
//!   participant's own round-1 commitment (and every peer commitment it
//!   received directly). A coordinator therefore cannot redirect the nonces to
//!   another message.
//! * **One-time state (§6.3, A11):** each session allocates a ledger record;
//!   the record is durably consumed, bound to `SHA-256(message)`, **before**
//!   `round2::sign` runs. Nonces live only in memory, are wiped after use, and
//!   any failure after consumption aborts the session permanently. A retry
//!   needs a new session, a new record, and fresh nonces.
//! * **Shares at rest** are sealed with ChaCha20-Poly1305 (see `seal`).
//!
//! ## Security claim it does NOT make
//!
//! * The trusted-dealer path (`recovery_profile == "dev-trusted-dealer"`)
//!   is **development only**: the dealing instance sees the whole secret and
//!   every share (sealed under *its* sealing key, so every participant instance
//!   must be configured with the same sealing key to load them).
//! * [`run_dkg`] exchanges round packages in-process. In production the
//!   round-1 packages must be delivered over an authenticated *broadcast*
//!   (every participant must see identical packages) and the round-2 packages
//!   over mutually authenticated, encrypted point-to-point channels (§6.4).
//!   This crate does not provide that transport.
//! * Share refresh and recover/replace are **not** supported (descriptor says
//!   so); FROST signing is not robust: one non-cooperating signer forces a
//!   retry with a different subset.
//! * Nonce state is in memory only: after a crash the session is lost (never
//!   resumed), which is the safe direction.
//!
//! ## Wire contract (integrator)
//!
//! * `protocol_version` = [`PROTOCOL_VERSION`] (`"frost-ed25519/2"`).
//! * Round 1 (broadcast, `to == None`): `payload` = serialized
//!   `frost_ed25519::round1::SigningCommitments` (frost 2.x serialization).
//!   Emitted by `start_signing_session` with `sequence == 1`.
//! * Round 2 (`share_producing_round == 2`), coordinator → participant:
//!   `payload` = serialized `frost_ed25519::SigningPackage` whose message is
//!   exactly `payload.message_or_digest`. Build it with [`build_signing_package`].
//!   The response is [`ProtocolStep::Share`] carrying the serialized
//!   `frost_ed25519::round2::SignatureShare` (32 bytes).
//! * `sequence` must strictly increase per sender within a session;
//!   `from_generation` must be at least the roster generation set with
//!   [`FrostEd25519Provider::set_roster_generation`] (senders without a
//!   roster entry have floor 0).
//! * Participant ids map to FROST identifiers via [`participant_identifier`]
//!   (`Identifier::derive(participant_id bytes)`).

mod seal;

use frost_ed25519 as frost;
use frost::keys::dkg;
use frost::keys::{KeyPackage, PublicKeyPackage};
use frost::round1::{SigningCommitments, SigningNonces};
use frost::round2::SignatureShare;
use frost::{Identifier, SigningPackage};
use oic_canonical_encoding::{canonical_bytes, from_canonical_bytes, sha256};
use oic_crypto_provider::*;
use oic_domain_types::*;
use parking_lot::Mutex;
use rand_core::{CryptoRngCore, OsRng};
use seal::{SealContext, SealingKey};
use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, BTreeSet};
use zeroize::{Zeroize, Zeroizing};

pub const BACKEND_ID: &str = "frost-ed25519";
/// `PeerMessage.protocol_version` for both signing rounds.
pub const PROTOCOL_VERSION: &str = "frost-ed25519/2";
/// Ceremony `recovery_profile` that selects the development-only trusted dealer.
pub const DEALER_PROFILE: &str = "dev-trusted-dealer";
/// Pinned upstream crate versions (as resolved in the workspace `Cargo.lock`).
pub const PINNED_VERSIONS: &str = "frost-ed25519=2.2.0;frost-core=2.2.0;ed25519-dalek=2.2.0;chacha20poly1305=0.10.1";
pub const MAX_PARTICIPANTS: u16 = 16;
pub const MIN_THRESHOLD: u16 = 2;
pub const SECURITY_NOTE: &str = "FROST(Ed25519, SHA-512) t-of-n threshold signing (RFC 9591) via frost-ed25519 2.x. \
Signatures are standard Ed25519. Use distributed key generation; the trusted-dealer profile is development only. \
No share refresh or recover/replace. Requires authenticated broadcast and encrypted point-to-point transport.";
/// Format tag inside a sealed share's plaintext.
pub const SHARE_FORMAT: &str = "oic-frost-ed25519-share/v1";

fn frost_err(what: &str, e: frost::Error) -> OicError {
    OicError::invalid_request(format!("{what}: {e}"))
}

fn not_found(detail: impl Into<String>) -> OicError {
    OicError::new(ErrorCode::NotFound, detail)
}

/// FROST identifier for a participant: `Identifier::derive(participant.as_bytes())`.
pub fn participant_identifier(participant: &ParticipantId) -> OicResult<Identifier> {
    Identifier::derive(participant.as_str().as_bytes()).map_err(|e| frost_err("participant identifier", e))
}

/// Coordinator helper (public data only): build the serialized round-2
/// `SigningPackage` from the participants' round-1 commitment payloads and the
/// exact message to sign.
pub fn build_signing_package(commitments: &[(ParticipantId, Bytes)], message: &[u8]) -> OicResult<Bytes> {
    let mut map = BTreeMap::new();
    for (p, bytes) in commitments {
        let c = SigningCommitments::deserialize(bytes.as_slice()).map_err(|e| frost_err("signing commitments", e))?;
        if map.insert(participant_identifier(p)?, c).is_some() {
            return Err(OicError::invalid_request(format!("duplicate commitments for {p}")));
        }
    }
    let pkg = SigningPackage::new(map, message);
    Ok(Bytes(pkg.serialize().map_err(|e| frost_err("signing package", e))?))
}

/// Sealed-share plaintext.
#[derive(Serialize, Deserialize)]
struct SharePlain {
    format: String,
    key_package: Bytes,
    public_key_package: Bytes,
}

impl Drop for SharePlain {
    fn drop(&mut self) {
        self.key_package.0.zeroize();
    }
}

struct LoadedKey {
    descriptor: KeyDescriptor,
    key_package: KeyPackage,
    public_key_package: PublicKeyPackage,
}

impl Drop for LoadedKey {
    fn drop(&mut self) {
        self.key_package.zeroize();
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum SessionState {
    AwaitingPackage,
    ShareReleased,
    Aborted(String),
}

struct Session {
    key_id: KeyId,
    key_epoch: Epoch,
    payload: NativeSigningPayload,
    /// Session participants → FROST identifier.
    ids: BTreeMap<ParticipantId, Identifier>,
    /// Generation floor per sender, snapshotted from the provider roster at start.
    roster: BTreeMap<ParticipantId, Epoch>,
    record_id: String,
    nonces: Option<SigningNonces>,
    own_commitment: SigningCommitments,
    peer_commitments: BTreeMap<ParticipantId, SigningCommitments>,
    last_sequence: BTreeMap<ParticipantId, u64>,
    signing_package: Option<SigningPackage>,
    state: SessionState,
}

impl Session {
    fn wipe_nonces(&mut self) {
        if let Some(mut n) = self.nonces.take() {
            n.zeroize();
        }
    }

    fn abort(&mut self, reason: String) {
        self.wipe_nonces();
        self.state = SessionState::Aborted(reason);
    }
}

impl Drop for Session {
    fn drop(&mut self) {
        self.wipe_nonces();
    }
}

struct DkgRound1 {
    ceremony: KeygenCeremony,
    secret: Option<dkg::round1::SecretPackage>,
}

struct DkgRound2 {
    ceremony: KeygenCeremony,
    secret: dkg::round2::SecretPackage,
}

enum DkgState {
    Round1(DkgRound1),
    Round2(DkgRound2),
}

impl Drop for DkgState {
    fn drop(&mut self) {
        match self {
            DkgState::Round1(r) => {
                if let Some(s) = r.secret.as_mut() {
                    s.zeroize();
                }
            }
            DkgState::Round2(r) => r.secret.zeroize(),
        }
    }
}

/// One participant's FROST(Ed25519) provider instance. See the crate docs.
pub struct FrostEd25519Provider {
    participant: ParticipantId,
    identifier: Identifier,
    sealing: SealingKey,
    rng: Mutex<Box<dyn CryptoRngCore + Send>>,
    keys: Mutex<BTreeMap<KeyId, LoadedKey>>,
    sessions: Mutex<BTreeMap<SigningSessionId, Session>>,
    roster: Mutex<BTreeMap<ParticipantId, Epoch>>,
    dkg: Mutex<BTreeMap<KeyId, DkgState>>,
}

impl FrostEd25519Provider {
    /// Create the instance for `participant` with a 32-byte share-sealing key
    /// and an injectable CSPRNG (nonces, DKG polynomials, sealing nonces).
    pub fn new(participant: ParticipantId, sealing_key: [u8; 32], rng: Box<dyn CryptoRngCore + Send>) -> OicResult<Self> {
        let identifier = participant_identifier(&participant)?;
        Ok(FrostEd25519Provider {
            participant,
            identifier,
            sealing: SealingKey::new(sealing_key),
            rng: Mutex::new(rng),
            keys: Mutex::new(BTreeMap::new()),
            sessions: Mutex::new(BTreeMap::new()),
            roster: Mutex::new(BTreeMap::new()),
            dkg: Mutex::new(BTreeMap::new()),
        })
    }

    /// [`Self::new`] with the operating-system CSPRNG.
    pub fn with_os_rng(participant: ParticipantId, sealing_key: [u8; 32]) -> OicResult<Self> {
        Self::new(participant, sealing_key, Box::new(OsRng))
    }

    pub fn participant(&self) -> &ParticipantId {
        &self.participant
    }

    /// Record the current signer-instance generation of a peer (§6.3). Peer
    /// messages from an older generation are rejected in sessions started
    /// afterwards. Generations only move forward; a lower value is refused.
    pub fn set_roster_generation(&self, participant: &ParticipantId, generation: Epoch) -> OicResult<()> {
        let mut roster = self.roster.lock();
        let cur = roster.entry(participant.clone()).or_default();
        if generation < *cur {
            return Err(OicError::resource_conflict(format!(
                "roster generation for {participant} cannot move backwards from {cur} to {generation}"
            )));
        }
        *cur = generation;
        Ok(())
    }

    /// Current roster generation floor for a participant (`Epoch(0)` if unset).
    pub fn roster_generation(&self, participant: &ParticipantId) -> Epoch {
        self.roster.lock().get(participant).copied().unwrap_or_default()
    }

    /// The one-time-state record id allocated for a session.
    pub fn session_record_id(&self, session_id: &SigningSessionId) -> OicResult<String> {
        self.sessions.lock().get(session_id).map(|s| s.record_id.clone()).ok_or_else(|| not_found(format!("unknown session {session_id}")))
    }

    /// Abort a session (e.g. coordinator timeout): wipes its nonces; the
    /// session never produces a share afterwards.
    pub fn abort_session(&self, session_id: &SigningSessionId, reason: &str) -> OicResult<()> {
        let mut sessions = self.sessions.lock();
        let s = sessions.get_mut(session_id).ok_or_else(|| not_found(format!("unknown session {session_id}")))?;
        s.abort(reason.to_string());
        Ok(())
    }

    fn seal_ctx<'a>(&'a self, key_id: &'a KeyId, key_epoch: Epoch, participant: &'a ParticipantId) -> SealContext<'a> {
        SealContext { backend_id: BACKEND_ID, key_id, key_epoch, participant }
    }

    fn seal_share(&self, key_id: &KeyId, key_epoch: Epoch, participant: &ParticipantId, kp: &KeyPackage, pkp: &PublicKeyPackage) -> OicResult<Bytes> {
        let plain = SharePlain {
            format: SHARE_FORMAT.into(),
            key_package: Bytes(kp.serialize().map_err(|e| frost_err("key package", e))?),
            public_key_package: Bytes(pkp.serialize().map_err(|e| frost_err("public key package", e))?),
        };
        let bytes = Zeroizing::new(canonical_bytes(&plain)?);
        let mut rng = self.rng.lock();
        Ok(Bytes(seal::seal(&self.sealing, &mut **rng, &self.seal_ctx(key_id, key_epoch, participant), &bytes)?))
    }

    fn validate_ceremony(&self, ceremony: &KeygenCeremony) -> OicResult<BTreeMap<ParticipantId, Identifier>> {
        check_topology(&self.capabilities(), ceremony.participants.len(), ceremony.threshold)?;
        let mut ids = BTreeMap::new();
        let mut seen = BTreeSet::new();
        for p in &ceremony.participants {
            let id = participant_identifier(p)?;
            if ids.insert(p.clone(), id).is_some() || !seen.insert(id) {
                return Err(OicError::invalid_request(format!("duplicate participant {p}")));
            }
        }
        Ok(ids)
    }

    fn descriptor_for(ceremony: &KeygenCeremony, pkp: &PublicKeyPackage) -> OicResult<KeyDescriptor> {
        let vk = pkp.verifying_key().serialize().map_err(|e| frost_err("verifying key", e))?;
        Ok(KeyDescriptor {
            key_id: ceremony.key_id.clone(),
            key_epoch: ceremony.key_epoch,
            scheme: SchemeId::Ed25519Pure,
            public_key: PublicKey { scheme: SchemeId::Ed25519Pure, bytes: Bytes(vk) },
            backend_id: BACKEND_ID.into(),
            backend_commit: PINNED_VERSIONS.into(),
            participants: ceremony.participants.clone(),
            threshold: ceremony.threshold,
            institution_id: ceremony.institution_id.clone(),
            environment_id: ceremony.environment_id.clone(),
            networks: ceremony.networks.clone(),
            recovery_profile: ceremony.recovery_profile.clone(),
        })
    }

    /// Validate key material against a descriptor and install it in memory.
    fn install(&self, descriptor: &KeyDescriptor, key_package: KeyPackage, public_key_package: PublicKeyPackage) -> OicResult<()> {
        if *key_package.identifier() != self.identifier {
            return Err(OicError::scope("key package identifier is not this participant"));
        }
        if key_package.verifying_key() != public_key_package.verifying_key() {
            return Err(OicError::scope("key package and public key package disagree on the group key"));
        }
        let vk = public_key_package.verifying_key().serialize().map_err(|e| frost_err("verifying key", e))?;
        if descriptor.public_key.scheme != SchemeId::Ed25519Pure || descriptor.public_key.bytes.as_slice() != vk.as_slice() {
            return Err(OicError::scope("share does not match the descriptor public key"));
        }
        if *key_package.min_signers() != descriptor.threshold {
            return Err(OicError::scope("share threshold does not match the descriptor"));
        }
        let expected: BTreeSet<Identifier> = descriptor.participants.iter().map(participant_identifier).collect::<OicResult<_>>()?;
        let actual: BTreeSet<Identifier> = public_key_package.verifying_shares().keys().copied().collect();
        if expected != actual {
            return Err(OicError::scope("public key package participants do not match the descriptor"));
        }
        if public_key_package.verifying_shares().get(&self.identifier) != Some(key_package.verifying_share()) {
            return Err(OicError::scope("own verifying share does not match the public key package"));
        }
        self.keys.lock().insert(descriptor.key_id.clone(), LoadedKey { descriptor: descriptor.clone(), key_package, public_key_package });
        Ok(())
    }

    // -----------------------------------------------------------------------
    // Distributed key generation (per participant)
    // -----------------------------------------------------------------------

    /// DKG round 1: returns this participant's serialized
    /// `dkg::round1::Package`, which must reach every other participant over
    /// an authenticated broadcast.
    pub fn dkg_part1(&self, ceremony: &KeygenCeremony) -> OicResult<Bytes> {
        self.validate_ceremony(ceremony)?;
        if !ceremony.participants.contains(&self.participant) {
            return Err(OicError::scope("this participant is not in the ceremony"));
        }
        let mut dkg_states = self.dkg.lock();
        if dkg_states.contains_key(&ceremony.key_id) {
            return Err(OicError::resource_conflict(format!("DKG for {} already in progress", ceremony.key_id)));
        }
        let n = ceremony.participants.len() as u16;
        let (secret, package) = {
            let mut rng = self.rng.lock();
            dkg::part1(self.identifier, n, ceremony.threshold, &mut **rng).map_err(|e| frost_err("dkg part1", e))?
        };
        let bytes = package.serialize().map_err(|e| frost_err("dkg round1 package", e))?;
        dkg_states.insert(ceremony.key_id.clone(), DkgState::Round1(DkgRound1 { ceremony: ceremony.clone(), secret: Some(secret) }));
        Ok(Bytes(bytes))
    }

    /// DKG round 2: given every *other* participant's round-1 package, returns
    /// the per-recipient serialized `dkg::round2::Package`s (secret; send only
    /// over encrypted, mutually authenticated channels).
    pub fn dkg_part2(&self, key_id: &KeyId, round1_packages: &BTreeMap<ParticipantId, Bytes>) -> OicResult<BTreeMap<ParticipantId, Bytes>> {
        let mut dkg_states = self.dkg.lock();
        let (ceremony, secret) = match dkg_states.get_mut(key_id) {
            Some(DkgState::Round1(r)) => {
                (r.ceremony.clone(), r.secret.take().ok_or_else(|| OicError::internal("DKG round-1 secret already used"))?)
            }
            _ => return Err(not_found(format!("no DKG round 1 in progress for {key_id}"))),
        };
        // From here the round-1 secret is moved; any failure ends this DKG run.
        let result = (|| {
            let r1 = self.round1_map(&ceremony, round1_packages)?;
            let (secret2, out) = dkg::part2(secret, &r1).map_err(|e| frost_err("dkg part2", e))?;
            let by_id: BTreeMap<Identifier, ParticipantId> =
                ceremony.participants.iter().map(|p| participant_identifier(p).map(|i| (i, p.clone()))).collect::<OicResult<_>>()?;
            let mut msgs = BTreeMap::new();
            for (id, pkg) in out {
                let p = by_id.get(&id).ok_or_else(|| OicError::internal("DKG produced a package for an unknown identifier"))?;
                msgs.insert(p.clone(), Bytes(pkg.serialize().map_err(|e| frost_err("dkg round2 package", e))?));
            }
            Ok((secret2, msgs))
        })();
        match result {
            Ok((secret2, msgs)) => {
                dkg_states.insert(key_id.clone(), DkgState::Round2(DkgRound2 { ceremony, secret: secret2 }));
                Ok(msgs)
            }
            Err(e) => {
                dkg_states.remove(key_id);
                Err(e)
            }
        }
    }

    /// DKG round 3: given the same round-1 packages and the round-2 packages
    /// addressed to this participant, derives this participant's key share,
    /// installs it in memory, and returns the key descriptor and the sealed
    /// share for storage.
    pub fn dkg_part3(
        &self,
        key_id: &KeyId,
        round1_packages: &BTreeMap<ParticipantId, Bytes>,
        round2_packages: &BTreeMap<ParticipantId, Bytes>,
    ) -> OicResult<(KeyDescriptor, Bytes)> {
        let state = {
            let mut dkg_states = self.dkg.lock();
            let st = dkg_states.remove(key_id).ok_or_else(|| not_found(format!("no DKG in progress for {key_id}")))?;
            if !matches!(st, DkgState::Round2(_)) {
                dkg_states.insert(key_id.clone(), st);
                return Err(OicError::invalid_request(format!("DKG for {key_id} is not at round 3")));
            }
            st
        };
        let DkgState::Round2(r) = &state else {
            return Err(OicError::internal("unreachable DKG state"));
        };
        let r1 = self.round1_map(&r.ceremony, round1_packages)?;
        let mut r2 = BTreeMap::new();
        for (p, bytes) in round2_packages {
            self.check_peer(&r.ceremony, p)?;
            let pkg = dkg::round2::Package::deserialize(bytes.as_slice()).map_err(|e| frost_err("dkg round2 package", e))?;
            r2.insert(participant_identifier(p)?, pkg);
        }
        let (kp, pkp) = dkg::part3(&r.secret, &r1, &r2).map_err(|e| frost_err("dkg part3", e))?;
        let descriptor = Self::descriptor_for(&r.ceremony, &pkp)?;
        let sealed = self.seal_share(key_id, r.ceremony.key_epoch, &self.participant, &kp, &pkp)?;
        self.install(&descriptor, kp, pkp)?;
        Ok((descriptor, sealed))
    }

    fn check_peer(&self, ceremony: &KeygenCeremony, p: &ParticipantId) -> OicResult<()> {
        if *p == self.participant || !ceremony.participants.contains(p) {
            return Err(OicError::scope(format!("{p} is not a peer in this ceremony")));
        }
        Ok(())
    }

    fn round1_map(&self, ceremony: &KeygenCeremony, packages: &BTreeMap<ParticipantId, Bytes>) -> OicResult<BTreeMap<Identifier, dkg::round1::Package>> {
        let mut r1 = BTreeMap::new();
        for (p, bytes) in packages {
            self.check_peer(ceremony, p)?;
            let pkg = dkg::round1::Package::deserialize(bytes.as_slice()).map_err(|e| frost_err("dkg round1 package", e))?;
            r1.insert(participant_identifier(p)?, pkg);
        }
        if r1.len() + 1 != ceremony.participants.len() {
            return Err(OicError::invalid_request("DKG requires exactly one round-1 package from every other participant"));
        }
        Ok(r1)
    }
}

/// Development harness: run the FROST DKG across in-process participant
/// instances, routing round-1 packages to everyone and each round-2 package
/// only to its recipient. In production the same per-participant calls run
/// over the authenticated transport. Every instance ends with its share
/// installed; the result carries each share sealed under its own instance's
/// sealing key.
pub fn run_dkg(providers: &[&FrostEd25519Provider], ceremony: &KeygenCeremony) -> OicResult<DistributedKeyResult> {
    let mine: BTreeSet<&ParticipantId> = providers.iter().map(|p| &p.participant).collect();
    let wanted: BTreeSet<&ParticipantId> = ceremony.participants.iter().collect();
    if mine != wanted || providers.len() != ceremony.participants.len() {
        return Err(OicError::invalid_request("run_dkg needs exactly one provider per ceremony participant"));
    }
    let mut round1 = BTreeMap::new();
    for p in providers {
        round1.insert(p.participant.clone(), p.dkg_part1(ceremony)?);
    }
    let others = |me: &ParticipantId| -> BTreeMap<ParticipantId, Bytes> {
        round1.iter().filter(|(k, _)| *k != me).map(|(k, v)| (k.clone(), v.clone())).collect()
    };
    // inbox[recipient][sender] = round-2 package
    let mut inbox: BTreeMap<ParticipantId, BTreeMap<ParticipantId, Bytes>> = BTreeMap::new();
    for p in providers {
        for (to, pkg) in p.dkg_part2(&ceremony.key_id, &others(&p.participant))? {
            inbox.entry(to).or_default().insert(p.participant.clone(), pkg);
        }
    }
    let mut descriptor: Option<KeyDescriptor> = None;
    let mut sealed_shares = Vec::new();
    for p in providers {
        let empty = BTreeMap::new();
        let mine = inbox.get(&p.participant).unwrap_or(&empty);
        let (d, sealed) = p.dkg_part3(&ceremony.key_id, &others(&p.participant), mine)?;
        match &descriptor {
            Some(prev) if *prev != d => return Err(OicError::internal("DKG participants derived different group keys")),
            _ => descriptor = Some(d),
        }
        sealed_shares.push((p.participant.clone(), sealed));
    }
    let descriptor = descriptor.ok_or_else(|| OicError::invalid_request("no participants"))?;
    Ok(DistributedKeyResult { descriptor, sealed_shares })
}

fn ed25519_verify(public_key: &PublicKey, message: &[u8], signature: &SignatureBytes) -> OicResult<()> {
    if public_key.scheme != SchemeId::Ed25519Pure || signature.scheme != SchemeId::Ed25519Pure {
        return Err(OicError::unsupported("FROST-Ed25519 verifies only Ed25519Pure keys and signatures"));
    }
    let pk: [u8; 32] = public_key.bytes.as_slice().try_into().map_err(|_| OicError::invalid_request("Ed25519 public key must be 32 bytes"))?;
    let vk = ed25519_dalek::VerifyingKey::from_bytes(&pk).map_err(|_| OicError::invalid_request("invalid Ed25519 public key"))?;
    let sig = ed25519_dalek::Signature::from_slice(signature.bytes.as_slice()).map_err(|_| OicError::invalid_signature("Ed25519 signature must be 64 bytes"))?;
    vk.verify_strict(message, &sig).map_err(|_| OicError::invalid_signature("Ed25519 verification failed"))
}

impl CryptoProvider for FrostEd25519Provider {
    fn capabilities(&self) -> BackendDescriptor {
        BackendDescriptor {
            backend_id: BACKEND_ID.into(),
            pinned_version: PINNED_VERSIONS.into(),
            license: "MIT OR Apache-2.0 (frost-ed25519); Apache-2.0 (this crate)".into(),
            scheme: SchemeId::Ed25519Pure,
            message_convention: MessageConvention::PureMessage,
            topology: ThresholdTopology::Threshold { max_participants: MAX_PARTICIPANTS, min_threshold: MIN_THRESHOLD },
            supports_refresh: false,
            supports_recover_or_replace: false,
            native_verifier_compatible: true,
            has_one_time_state: true,
            share_producing_round: 2,
            security_note: SECURITY_NOTE.into(),
        }
    }

    /// Trusted-dealer key generation, only when `recovery_profile ==
    /// "dev-trusted-dealer"`. Real deployments use [`run_dkg`] /
    /// `dkg_part1..3`.
    fn generate_distributed_key(&self, ceremony: &KeygenCeremony) -> OicResult<DistributedKeyResult> {
        if ceremony.recovery_profile != DEALER_PROFILE {
            return Err(OicError::unsupported(format!(
                "{BACKEND_ID}: a single instance cannot run a distributed key generation; use run_dkg / dkg_part1..3 \
                 (the trusted dealer is only available with recovery_profile \"{DEALER_PROFILE}\", development only)"
            )));
        }
        let ids = self.validate_ceremony(ceremony)?;
        let id_list: Vec<Identifier> = ceremony.participants.iter().map(|p| ids[p]).collect();
        let n = ceremony.participants.len() as u16;
        let (shares, pkp) = {
            let mut rng = self.rng.lock();
            frost::keys::generate_with_dealer(n, ceremony.threshold, frost::keys::IdentifierList::Custom(&id_list), &mut **rng)
                .map_err(|e| frost_err("trusted dealer", e))?
        };
        let descriptor = Self::descriptor_for(ceremony, &pkp)?;
        let mut sealed_shares = Vec::with_capacity(shares.len());
        for p in &ceremony.participants {
            let share = shares.get(&ids[p]).ok_or_else(|| OicError::internal("dealer omitted a share"))?.clone();
            let mut kp = KeyPackage::try_from(share).map_err(|e| frost_err("dealer share verification", e))?;
            let sealed = self.seal_share(&ceremony.key_id, ceremony.key_epoch, p, &kp, &pkp);
            kp.zeroize();
            sealed_shares.push((p.clone(), sealed?));
        }
        Ok(DistributedKeyResult { descriptor, sealed_shares })
    }

    fn load_share(&self, descriptor: &KeyDescriptor, participant: &ParticipantId, sealed: &Bytes) -> OicResult<()> {
        if descriptor.backend_id != BACKEND_ID {
            return Err(OicError::scope(format!("descriptor backend {} is not {BACKEND_ID}", descriptor.backend_id)));
        }
        if descriptor.scheme != SchemeId::Ed25519Pure {
            return Err(OicError::unsupported(format!("{BACKEND_ID} supports only Ed25519Pure")));
        }
        if *participant != self.participant || !descriptor.participants.contains(participant) {
            return Err(OicError::scope("share is not for this participant instance"));
        }
        let plain = seal::open(&self.sealing, &self.seal_ctx(&descriptor.key_id, descriptor.key_epoch, participant), sealed.as_slice())?;
        let share: SharePlain = from_canonical_bytes(&plain)?;
        if share.format != SHARE_FORMAT {
            return Err(OicError::invalid_request(format!("unknown share format {}", share.format)));
        }
        let kp = KeyPackage::deserialize(share.key_package.as_slice()).map_err(|e| frost_err("key package", e))?;
        let pkp = PublicKeyPackage::deserialize(share.public_key_package.as_slice()).map_err(|e| frost_err("public key package", e))?;
        self.install(descriptor, kp, pkp)
    }

    fn start_signing_session(
        &self,
        session_id: &SigningSessionId,
        key_id: &KeyId,
        payload: &NativeSigningPayload,
        participants: &[ParticipantId],
        ledger: &dyn OneTimeStateLedger,
        signer_generation: Epoch,
    ) -> OicResult<ProtocolStep> {
        if payload.required_key_id != *key_id {
            return Err(OicError::scope("payload required_key_id does not match session key"));
        }
        if payload.scheme_id != SchemeId::Ed25519Pure {
            return Err(OicError::unsupported(format!("{BACKEND_ID} signs only Ed25519Pure payloads")));
        }
        let (key_epoch, signing_share, threshold, members) = {
            let keys = self.keys.lock();
            let k = keys.get(key_id).ok_or_else(|| not_found(format!("no share loaded for key {key_id}")))?;
            (k.descriptor.key_epoch, *k.key_package.signing_share(), k.descriptor.threshold, k.descriptor.participants.clone())
        };
        let mut ids = BTreeMap::new();
        for p in participants {
            if !members.contains(p) {
                return Err(OicError::scope(format!("{p} is not a participant of key {key_id}")));
            }
            if ids.insert(p.clone(), participant_identifier(p)?).is_some() {
                return Err(OicError::invalid_request(format!("duplicate participant {p}")));
            }
        }
        if !ids.contains_key(&self.participant) {
            return Err(OicError::scope("this participant is not in the signing set"));
        }
        if ids.len() < threshold as usize {
            return Err(OicError::invalid_request(format!("signing set of {} is below threshold {threshold}", ids.len())));
        }
        let roster: BTreeMap<ParticipantId, Epoch> = {
            let r = self.roster.lock();
            r.clone()
        };
        let mut sessions = self.sessions.lock();
        if sessions.contains_key(session_id) {
            return Err(OicError::resource_conflict(format!("session {session_id} already exists")));
        }
        let record = ledger.allocate(key_id, key_epoch, signer_generation, session_id)?;
        let (nonces, commitments) = {
            let mut guard = self.rng.lock();
            let mut rng: &mut (dyn CryptoRngCore + Send) = &mut **guard;
            frost::round1::commit(&signing_share, &mut rng)
        };
        let commitment_bytes = commitments.serialize().map_err(|e| frost_err("signing commitments", e))?;
        sessions.insert(
            session_id.clone(),
            Session {
                key_id: key_id.clone(),
                key_epoch,
                payload: payload.clone(),
                ids,
                roster,
                record_id: record.record_id,
                nonces: Some(nonces),
                own_commitment: commitments,
                peer_commitments: BTreeMap::new(),
                last_sequence: BTreeMap::new(),
                signing_package: None,
                state: SessionState::AwaitingPackage,
            },
        );
        Ok(ProtocolStep::Send(vec![PeerMessage {
            session_id: session_id.clone(),
            key_id: key_id.clone(),
            key_epoch,
            from: self.participant.clone(),
            from_generation: signer_generation,
            to: None,
            round: 1,
            sequence: 1,
            protocol_version: PROTOCOL_VERSION.into(),
            payload: Bytes(commitment_bytes),
        }]))
    }

    fn advance_protocol(&self, session_id: &SigningSessionId, message: &PeerMessage, ledger: &dyn OneTimeStateLedger) -> OicResult<ProtocolStep> {
        let mut sessions = self.sessions.lock();
        let s = sessions.get_mut(session_id).ok_or_else(|| not_found(format!("unknown session {session_id}")))?;
        match &s.state {
            SessionState::AwaitingPackage => {}
            SessionState::ShareReleased => {
                return Ok(ProtocolStep::Aborted("session already released its share; nonces are consumed and wiped".into()))
            }
            SessionState::Aborted(r) => return Ok(ProtocolStep::Aborted(format!("session aborted: {r}"))),
        }
        // Context binding (§6.4).
        if message.session_id != *session_id || message.key_id != s.key_id || message.key_epoch != s.key_epoch {
            return Err(OicError::scope("peer message session/key/epoch does not match the session"));
        }
        if message.protocol_version != PROTOCOL_VERSION {
            return Err(OicError::invalid_request(format!("protocol_version must be {PROTOCOL_VERSION}")));
        }
        if message.to.as_ref().is_some_and(|to| *to != self.participant) {
            return Err(OicError::scope("peer message is addressed to another participant"));
        }
        if message.from == self.participant {
            return Err(OicError::scope("peer message claims to be from this participant"));
        }
        let floor = s.roster.get(&message.from).copied().unwrap_or_default();
        if message.from_generation < floor {
            return Err(OicError::scope(format!(
                "message from {} has stale generation {} below roster generation {floor}",
                message.from, message.from_generation
            )));
        }
        if let Some(last) = s.last_sequence.get(&message.from) {
            if message.sequence <= *last {
                return Err(OicError::resource_conflict(format!("non-monotonic sequence {} from {} (last {last})", message.sequence, message.from)));
            }
        }

        match message.round {
            1 => {
                if !s.ids.contains_key(&message.from) {
                    return Err(OicError::scope(format!("{} is not in this signing set", message.from)));
                }
                if s.peer_commitments.contains_key(&message.from) {
                    return Err(OicError::resource_conflict(format!("duplicate round-1 commitment from {}", message.from)));
                }
                let c = SigningCommitments::deserialize(message.payload.as_slice()).map_err(|e| frost_err("signing commitments", e))?;
                s.peer_commitments.insert(message.from.clone(), c);
                s.last_sequence.insert(message.from.clone(), message.sequence);
                Ok(ProtocolStep::Waiting)
            }
            2 => {
                let pkg = SigningPackage::deserialize(message.payload.as_slice()).map_err(|e| frost_err("signing package", e))?;
                // Binding checks: all before touching the ledger or nonces.
                if pkg.message().as_slice() != s.payload.message_or_digest.as_slice() {
                    return Err(OicError::scope("signing package message differs from the authorized session payload"));
                }
                let pkg_ids: BTreeSet<Identifier> = pkg.signing_commitments().keys().copied().collect();
                let session_ids: BTreeSet<Identifier> = s.ids.values().copied().collect();
                if pkg_ids != session_ids {
                    return Err(OicError::scope("signing package participant set differs from the session participant set"));
                }
                if pkg.signing_commitment(&self.identifier) != Some(s.own_commitment) {
                    return Err(OicError::scope("signing package does not carry this participant's round-1 commitment"));
                }
                for (p, c) in &s.peer_commitments {
                    if pkg.signing_commitment(&s.ids[p]) != Some(*c) {
                        return Err(OicError::scope(format!("signing package commitment for {p} differs from the one {p} sent")));
                    }
                }
                s.last_sequence.insert(message.from.clone(), message.sequence);

                // §6.3: durable consumption precedes the share.
                let message_hash = sha256(s.payload.message_or_digest.as_slice());
                if let Err(e) = ledger.consume(&s.record_id, message_hash) {
                    s.abort(format!("one-time record consume failed: {}", e.detail));
                    return Err(e);
                }
                let Some(nonces) = s.nonces.take() else {
                    s.abort("nonces missing".into());
                    return Err(OicError::internal("session nonces missing"));
                };
                let mut nonces = nonces;
                let signed = {
                    let keys = self.keys.lock();
                    match keys.get(&s.key_id) {
                        Some(k) => frost::round2::sign(&pkg, &nonces, &k.key_package).map_err(|e| frost_err("round2 sign", e)),
                        None => Err(not_found("share unloaded during session")),
                    }
                };
                nonces.zeroize();
                match signed {
                    Ok(share) => {
                        s.signing_package = Some(pkg);
                        s.state = SessionState::ShareReleased;
                        Ok(ProtocolStep::Share(Bytes(share.serialize())))
                    }
                    Err(e) => {
                        s.abort(e.detail.clone());
                        Err(e)
                    }
                }
            }
            r => Err(OicError::invalid_request(format!("FROST signing has rounds 1 and 2; got {r}"))),
        }
    }

    fn aggregate(&self, session_id: &SigningSessionId, shares: &[(ParticipantId, Bytes)]) -> OicResult<SignatureBytes> {
        let (pkg, ids, key_id, message) = {
            let sessions = self.sessions.lock();
            let s = sessions.get(session_id).ok_or_else(|| not_found(format!("unknown session {session_id}")))?;
            let pkg = s
                .signing_package
                .clone()
                .ok_or_else(|| OicError::invalid_request("this instance holds no signing package for the session (it has not signed it)"))?;
            (pkg, s.ids.clone(), s.key_id.clone(), s.payload.message_or_digest.clone())
        };
        let (pkp, public_key) = {
            let keys = self.keys.lock();
            let k = keys.get(&key_id).ok_or_else(|| not_found(format!("key {key_id} not loaded")))?;
            (k.public_key_package.clone(), k.descriptor.public_key.clone())
        };
        let by_id: BTreeMap<Identifier, &ParticipantId> = ids.iter().map(|(p, i)| (*i, p)).collect();
        let mut map = BTreeMap::new();
        for (p, bytes) in shares {
            let id = ids.get(p).ok_or_else(|| OicError::scope(format!("share from {p}, who is not in the signing set")))?;
            let share = SignatureShare::deserialize(bytes.as_slice()).map_err(|e| OicError::invalid_signature(format!("share from {p}: {e}")))?;
            if map.insert(*id, share).is_some() {
                return Err(OicError::invalid_request(format!("duplicate share from {p}")));
            }
        }
        if map.len() != ids.len() {
            return Err(OicError::invalid_request(format!("need shares from all {} session signers, got {}", ids.len(), map.len())));
        }
        let sig = frost::aggregate(&pkg, &map, &pkp).map_err(|e| match e.culprit() {
            Some(c) => OicError::invalid_signature(format!(
                "invalid signature share from {}; no signature produced",
                by_id.get(&c).map(|p| p.as_str()).unwrap_or("unknown")
            )),
            None => OicError::invalid_signature(format!("aggregation failed: {e}")),
        })?;
        let bytes = sig.serialize().map_err(|e| frost_err("signature", e))?;
        let out = SignatureBytes { scheme: SchemeId::Ed25519Pure, bytes: Bytes(bytes) };
        ed25519_verify(&public_key, message.as_slice(), &out)?;
        Ok(out)
    }

    fn verify_result(&self, public_key: &PublicKey, payload: &NativeSigningPayload, signature: &SignatureBytes) -> OicResult<()> {
        if payload.scheme_id != SchemeId::Ed25519Pure {
            return Err(OicError::unsupported(format!("{BACKEND_ID} verifies only Ed25519Pure payloads")));
        }
        ed25519_verify(public_key, payload.message_or_digest.as_slice(), signature)
    }
}
